<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Mini Spreadsheet</title>
  <style>
    #grid {
      display: table;
      border-collapse: collapse;
      min-width: 600px;
      min-height: 400px;
      margin-bottom: 1em;
    }
    #grid th, #grid td {
      padding: 2px;
      text-align: center;
    }
    #grid input {
      width: 58px;
      height: 20px;
      text-align: right;
      border: 1px solid #ccc;
      margin: 0;
    }
    th {
      background-color: #f4f4f4;
    }
    textarea {
      width: 600px;
      font-family: monospace;
      white-space: pre;
    }
  </style>
</head>
<body>
  <div id="grid"></div>
  <button id="export">Export CSV</button>
  <textarea id="csv" readonly></textarea>

  <script>
    const cells = {};
    const validCellIds = new Set();
    for (let row = 1; row <= 10; row++) {
      for (const col of 'ABCDEFGHIJ'.split('')) {
        const id = `${col}${row}`;
        validCellIds.add(id);
        cells[id] = {
          raw: '',
          display: '',
          effectiveValue: 0,
          dependencies: [],
          dependents: []
        };
      }
    }

    const evaluatingPath = [];

    function getEffectiveValue(cellId) {
      if (evaluatingPath.includes(cellId)) throw new Error('Cycle detected');
      evaluatingPath.push(cellId);
      try {
        const cell = cells[cellId];
        let result;
        if (cell.raw.startsWith('=')) {
          // Parse and evaluate formula
          if (!cell.formula || !cell.ast) return 0;
          result = evalFormula(cell.ast, {});
        } else {
          if (cell.raw === '') {
            result = 0;
            cell.display = '';
          } else {
            const num = parseFloat(cell.raw);
            if (!isNaN(num)) {
              result = num;
              cell.display = num.toString();
            } else {
              result = 0;
              cell.display = cell.raw;
            }
          }
        }
        return result;
      } finally {
        evaluatingPath.pop();
      }
    }

    function evalFormula(ast, values) {
      if (ast.type === 'number') return ast.value;
      if (ast.type === 'variable') {
        const val = getEffectiveValue(ast.name);
        return isNaN(val) ? 0 : val;
      }
      const left = evalFormula(ast.left, values);
      const right = evalFormula(ast.right, values);
      switch (ast.op) {
        case '+': return left + right;
        case '-': return left - right;
        case '*': return left * right;
        case '/': 
          if (right === 0) throw new Error('Division by zero');
          return left / right;
      }
    }

    function parseFormula(formulaStr) {
      const tokens = formulaStr.slice(1).match(/([+\-*/()])|(\d+\.?\d*)|([A-J][1-9]\d?)/g) || [];
      let pos = 0;

      function nextToken() { return tokens[pos++]; }
      function peekToken() { return tokens[pos]; }

      function parseExpr() {
        const left = parseTerm();
        while (peekToken() === '+' || peekToken() === '-') {
          const op = nextToken();
          const right = parseTerm();
          left.push(op, right);
        }
        return left;
      }

      function parseTerm() {
        let left = parseFactor();
        while (peekToken() === '*' || peekToken() === '/') {
          const op = nextToken();
          const right = parseFactor();
          left.push(op, right);
        }
        return left;
      }

      function parseFactor() {
        const token = nextToken();
        if (token === '(') {
          const expr = parseExpr();
          expect(')');
          return expr;
        } else if (/^-?\d+\.?\d*$/.test(token)) {
          return { type: 'number', value: parseFloat(token) };
        } else if (/^[A-J][1-9]\d?$/.test(token)) {
          if (!validCellIds.has(token)) throw new Error('Invalid cell reference');
          return { type: 'variable', name: token };
        } else {
          throw new Error('Unexpected token');
        }
      }

      function expect(token) {
        if (nextToken() !== token) throw new Error(`Expected ${token}`);
      }

      try {
        const ast = parseExpr();
        if (pos < tokens.length) throw new Error('Unexpected end of input');

        // Collect dependencies
        const dependencies = [];
        function collect(node) {
          if (node.type === 'variable') dependencies.push(node.name);
          else if (Array.isArray(node)) {
            for (let i = 1; i < node.length; i += 2) collect(node[i+1]);
          }
        }
        collect(ast);

        return { valid: true, ast, dependencies };
      } catch (e) {
        console.error(e);
        return { valid: false };
      }
    }

    function evaluateCell(cellId) {
      try {
        const cell = cells[cellId];
        if (cell.raw.startsWith('=')) {
          const parseResult = parseFormula(cell.raw);
          if (!parseResult.valid) throw new Error('Invalid formula');

          cell.dependencies = [];
          for (const dep of parseResult.dependencies) {
            cell.dependencies.push(dep);
            cells[dep].dependents.push(cellId);
          }
          cell.ast = parseResult.ast;
        } else {
          // Remove old dependencies
          while (cell.dependencies.length > 0) {
            const dep = cell.dependencies.pop();
            const idx = cells[dep].dependents.indexOf(cellId);
            if (idx !== -1) cells[dep].dependents.splice(idx, 1);
          }
        }

        const value = getEffectiveValue(cellId);

        if (value instanceof Error) {
          if (value.message.includes('Cycle')) {
            cell.display = '#CYCLE';
            cell.effectiveValue = '#CYCLE';
          } else {
            cell.display = '#ERR';
            cell.effectiveValue = '#ERR';
          }
        } else {
          cell.effectiveValue = isNaN(value) ? 0 : value;
          if (typeof value === 'number') {
            cell.display = Number.isInteger(value) ? value.toString() : value.toPrecision(6);
          } else {
            cell.display = value;
          }
        }

        return true;
      } catch (e) {
        console.error(e);
        cells[cellId].display = '#ERR';
        return false;
      }
    }

    function updateDependent(cellId) {
      const result = evaluateCell(cellId);
      if (result && cells[cellId].dependents.length > 0) {
        for (const dep of cells[cellId].dependents) {
          updateDependent(dep);
        }
      }
    }

    // Initialize grid
    const gridDiv = document.getElementById('grid');
    for (let row = 1; row <= 10; row++) {
      const tr = document.createElement('tr');

      const thRow = document.createElement('th');
      thRow.textContent = row;
      tr.appendChild(thRow);

      for (const col of 'ABCDEFGHIJ'.split('')) {
        const cellId = `${col}${row}`;
        const td = document.createElement('td');
        const input = document.createElement('input');
        input.id = `cell-${cellId}`;
        input.dataset.cellid = cellId;
        td.appendChild(input);
        tr.appendChild(td);
      }

      gridDiv.appendChild(tr);
    }

    // Add column headers
    const colHeaderTr = document.createElement('tr');
    colHeaderTr.innerHTML = '<th></th>';
    for (const col of 'ABCDEFGHIJ'.split('')) {
      const th = document.createElement('th');
      th.textContent = col;
      colHeaderTr.appendChild(th);
    }
    gridDiv.insertBefore(colHeaderTr, gridDiv.firstChild);

    // Event listeners
    document.querySelectorAll('#grid input').forEach(input => {
      input.addEventListener('focus', () => {
        const id = input.dataset.cellid;
        input.value = cells[id].raw;
      });

      input.addEventListener('blur', () => {
        const id = input.dataset.cellid;
        const newValue = input.value.trim();

        if (newValue !== cells[id].raw) {
          // Remove old dependencies
          while (cells[id].dependencies.length > 0) {
            const dep = cells[id].dependencies.pop();
            const idx = cells[dep].dependents.indexOf(id);
            if (idx !== -1) cells[dep].dependents.splice(idx, 1);
          }

          cells[id].raw = newValue;
          evaluateCell(id);

          for (const dep of cells[id].dependents) {
            updateDependent(dep);
          }
        }

        input.value = cells[id].display;
      });

      input.addEventListener('keydown', e => {
        if (e.key === 'Enter') {
          const id = input.dataset.cellid;
          const newValue = input.value.trim();

          if (newValue !== cells[id].raw) {
            // Remove old dependencies
            while (cells[id].dependencies.length > 0) {
              const dep = cells[id].dependencies.pop();
              const idx = cells[dep].dependents.indexOf(id);
              if (idx !== -1) cells[dep].dependents.splice(idx, 1);
            }

            cells[id].raw = newValue;
            evaluateCell(id);

            for (const dep of cells[id].dependents) {
              updateDependent(dep);
            }
          }

          input.value = cells[id].display;
        }
      });
    });

    document.getElementById('export').addEventListener('click', () => {
      let csv = '';
      for (let row = 1; row <= 10; row++) {
        const line = [];
        for (const col of 'ABCDEFGHIJ'.split('')) {
          const id = `${col}${row}`;
          if (cells[id].display === '#CYCLE' || cells[id].display === '#ERR') {
            line.push(cells[id].display);
          } else if (!isNaN(parseFloat(cells[id].display))) {
            line.push(Number.isInteger(parseFloat(cells[id].display)) ? 
              parseFloat(cells[id].display).toString() : 
              parseFloat(cells[id].display).toPrecision(6));
          } else {
            line.push('0');
          }
        }
        csv += line.join(',') + '\n';
      }
      document.getElementById('csv').value = csv.trim();
    });

    // Initialize displays
    for (const id in cells) {
      evaluateCell(id);
    }

    window.sheet = {
      set(id, value) {
        const input = document.querySelector(`input[data-cellid="${id}"]`);
        if (!input) return;

        input.value = value.trim();
        if (value.trim() !== cells[id].raw) {
          // Remove old dependencies
          while (cells[id].dependencies.length > 0) {
            const dep = cells[id].dependencies.pop();
            const idx = cells[dep].dependents.indexOf(id);
            if (idx !== -1) cells[dep].dependents.splice(idx, 1);
          }

          cells[id].raw = value.trim();
          evaluateCell(id);

          for (const dep of cells[id].dependents) {
            updateDependent(dep);
          }
        }

        input.value = cells[id].display;
      },
      get(id) {
        return cells[id].display;
      },
      raw(id) {
        return cells[id].raw;
      }
    };
  </script>
</body>
